import React, { useEffect, useState } from "react";
import { getDailyBoxOffice, getMovieDetail } from "../api/boxofficeApi"; // 경로가 맞는지 확인해주세요
import { getPosterFromTMDB } from "../api/tmdbApi"; // 경로가 맞는지 확인해주세요
import MovieCard from "../components/MovieCard"; // 경로가 맞는지 확인해주세요

function HomePage() {
  const [movies, setMovies] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchBoxOffice = async () => {
      setLoading(true);
      setError(null); // API 호출 시작 시 에러 상태 초기화

      try {
        // 어제 날짜를 'YYYYMMDD' 형식으로 계산
        const today = new Date();
        today.setDate(today.getDate() - 1);
        const targetDt = `${today.getFullYear()}${String(
          today.getMonth() + 1
        ).padStart(2, "0")}${String(today.getDate()).padStart(2, "0")}`;

        const boxOfficeList = await getDailyBoxOffice(targetDt);

        if (boxOfficeList.length === 0) {
          throw new Error("박스오피스 정보를 가져올 수 없습니다.");
        }

        const enrichedMovies = await Promise.all(
          boxOfficeList.map(async (movie) => {
            // 각 영화의 상세 정보와 포스터 URL을 비동기적으로 가져옴
            const detail = await getMovieDetail(movie.movieCd);
            const year = detail.openDt?.substring(0, 4) || "";

            const posterUrl = await getPosterFromTMDB(movie.movieNm, year, {
              movieNmEn: detail.movieNmEn,
              nation: detail.nations?.[0]?.nationNm, // 상세 정보의 국가명 사용
            });

            // MovieCard에 전달할 데이터를 상세하게 구조화
            return {
              id: movie.movieCd,
              title: movie.movieNm,
              englishTitle: detail.movieNmEn || "",
              poster_path:
                posterUrl ||
                "https://via.placeholder.com/400x600?text=No+Image",
              details: {
                Release: detail.openDt
                  ? `${detail.openDt.substring(0, 4)}.${detail.openDt.substring(
                      4,
                      6
                    )}.${detail.openDt.substring(6, 8)}`
                  : "N/A",
                Director: detail.directors?.[0]?.peopleNm || "N/A",
                Actors:
                  detail.actors?.slice(0, 3).map((a) => a.peopleNm).join(", ") || "N/A",
                Genre:
                  detail.genres?.map((g) => g.genreNm).join(", ") || "N/A",
                Rating: detail.audits?.[0]?.watchGradeNm || "N/A",
              },
            };
          })
        );

        setMovies(enrichedMovies);
      } catch (err) {
        console.error("박스오피스 데이터를 불러오는 데 실패했습니다:", err);
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchBoxOffice();
  }, []); // 컴포넌트가 처음 마운트될 때 한 번만 실행

  if (loading) {
    return <div style={styles.message}>로딩 중...</div>;
  }

  if (error) {
    return <div style={styles.message}>에러: {error}</div>;
  }

  return (
    <div style={styles.container}>
      <h1 style={styles.title}>🍿 일별 박스오피스</h1>
      <div style={styles.movieGrid}>
        {movies.map((movie) => (
          <MovieCard key={movie.id} movie={movie} />
        ))}
      </div>
    </div>
  );
}

// 스타일 객체
const styles = {
  container: {
    width: "100%",
    maxWidth: "1200px",
    margin: "0 auto",
    padding: "2rem",
    boxSizing: "border-box",
  },
  title: {
    fontSize: "2.5rem",
    textAlign: "center",
    marginBottom: "3rem",
    fontWeight: "bold",
  },
  movieGrid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fill, minmax(250px, 1fr))", // 반응형 그리드
    gap: "2rem",
  },
  message: {
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    height: "50vh",
    fontSize: "1.5rem",
  },
};

export default HomePage;
